<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute, RouterLink } from 'vue-router'
import { products, formatIDR } from '../data/products'
import { origins } from '../data/origins'
import { useCartStore } from '../stores/cart'
const route=useRoute(), cart=useCartStore()
const product=computed(()=>products.find(p=>p.id===route.params.id))
const size=ref('250g'), grind=ref('Whole bean')
watch(()=>route.params.id,()=>{size.value='250g';grind.value='Whole bean'})
const price=computed(()=>product.value?.sizes.find(s=>s.label===size.value)?.price||0)
const related=computed(()=>products.filter(p=>p.id!==product.value?.id&&(p.region===product.value?.region||p.process===product.value?.process)).slice(0,3))
const productOrigin=computed(()=>origins.find(origin=>origin.products.includes(product.value?.id)))
</script>
<template><div v-if="product" class="product-page"><div class="breadcrumbs"><RouterLink to="/">Beranda</RouterLink><span>/</span><RouterLink to="/shop">Kopi pilihan</RouterLink><span>/</span><b>{{ product.name }}</b></div><div class="product-detail-grid"><div class="detail-image"><img :src="product.image" :alt="`Kopi ${product.name} dari ${product.origin}`"/><span class="detail-image-label">DHARMA · ORIGIN SERIES</span><span class="detail-image-num">{{ product.id.slice(0,2).toUpperCase() }} / 0{{ product.roast }}</span></div><div class="detail-info"><span class="section-index">SINGLE ORIGIN · {{ product.region.toUpperCase() }}</span><h1>{{ product.name }}</h1><p class="detail-origin"><RouterLink v-if="productOrigin" :to="`/origin/${productOrigin.slug}`">{{ product.origin }} <span>↗</span></RouterLink><template v-else>{{ product.origin }}</template> <span>·</span> {{ product.altitude }}</p><p class="detail-description">{{ product.note }}</p><div class="detail-tags"><span v-for="taste in product.tasting" :key="taste">{{ taste }}</span></div><div class="detail-profile"><span class="profile-heading">PROFIL CANGKIR</span><div v-for="metric in [{label:'Keasaman',value:product.acidity},{label:'Body',value:product.body},{label:'Kemanisan',value:product.sweetness}]" :key="metric.label" class="profile-row"><span>{{ metric.label }}</span><div class="profile-track"><i :style="{width:`${metric.value*20}%`}"></i></div><b>{{ metric.value }}/5</b></div></div><div class="detail-facts"><div><span>PROSES</span><b>{{ product.process }}</b></div><div><span>ROAST</span><b>{{ product.roastLabel }}</b></div><div><span>VARIETAS</span><b>{{ product.variety }}</b></div></div><div class="variant-select"><label>UKURAN KEMASAN</label><div class="size-options"><button v-for="item in product.sizes" :key="item.label" :class="{chosen:size===item.label}" @click="size=item.label"><span>{{ item.label }}</span><small>{{ formatIDR(item.price) }}</small></button></div></div><div class="variant-select"><label>GILINGAN</label><select v-model="grind"><option v-for="item in product.grinds" :key="item">{{ item }}</option></select></div><div class="detail-buy"><div><span>HARGA</span><b>{{ formatIDR(price) }}</b><small>Termasuk pajak</small></div><button class="button button-coral" @click="cart.add(product.id,size,grind)">Tambah ke tas <span>↗</span></button></div><p class="demo-disclaimer">Produk dan harga di halaman ini adalah contoh untuk demo frontend.</p></div></div><section class="related-section"><div class="section-heading" data-aos="fade-up"><div><span class="section-index">MUNGKIN KAMU SUKA</span><h2>Satu cerita <em>lainnya.</em></h2></div><RouterLink to="/shop" class="text-link">Semua kopi <span>↗</span></RouterLink></div><div class="related-grid"><article v-for="(item, index) in related" :key="item.id" class="related-item" data-aos="fade-up" :data-aos-delay="index * 50"><RouterLink :to="`/product/${item.id}`"><img :src="item.image" :alt="item.name" loading="lazy"/><span>{{ item.region }}</span><h3>{{ item.name }}</h3><p>{{ formatIDR(item.price) }} / 250g</p></RouterLink></article></div></section></div><div v-else class="not-found"><span>✳</span><h1>Kopi ini belum ditemukan.</h1><RouterLink to="/shop" class="button button-dark">Kembali ke katalog</RouterLink></div></template>
